// Pure-JavaScript SHA-1 implementation (FIPS 180-1).
// Operates on Uint8Array byte arrays; no external or built-in crypto modules.

const K = [0x5a827999, 0x6ed9eba1, 0x8f1bbcdc, 0xca62c1d6];

function rotl(x, n) {
  return ((x << n) | (x >>> (32 - n))) | 0;
}

function f(t, b, c, d) {
  if (t < 20) return (b & c) | (~b & d);
  if (t < 40) return b ^ c ^ d;
  if (t < 60) return (b & c) | (b & d) | (c & d);
  return b ^ c ^ d;
}

// One-shot SHA-1 digest of a Uint8Array. Returns a 20-byte Uint8Array.
export function sha1(message) {
  const ml = message.length;
  const bitLenHi = Math.floor(ml / 0x20000000);
  const bitLenLo = (ml * 8) >>> 0;

  // Padding: append 0x80, then zeros, then 64-bit big-endian bit length.
  let total = ml + 1;
  while (total % 64 !== 56) total++;
  total += 8;
  const padded = new Uint8Array(total);
  padded.set(message);
  padded[ml] = 0x80;
  const dv = new DataView(padded.buffer);
  dv.setUint32(total - 8, bitLenHi, false);
  dv.setUint32(total - 4, bitLenLo, false);

  let h0 = 0x67452301 | 0;
  let h1 = 0xefcdab89 | 0;
  let h2 = 0x98badcfe | 0;
  let h3 = 0x10325476 | 0;
  let h4 = 0xc3d2e1f0 | 0;

  const w = new Int32Array(80);

  for (let offset = 0; offset < total; offset += 64) {
    for (let t = 0; t < 16; t++) {
      w[t] = dv.getUint32(offset + t * 4, false) | 0;
    }
    for (let t = 16; t < 80; t++) {
      w[t] = rotl(w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16], 1);
    }

    let a = h0, b = h1, c = h2, d = h3, e = h4;

    for (let t = 0; t < 80; t++) {
      const temp = (rotl(a, 5) + f(t, b, c, d) + e + w[t] + K[(t / 20) | 0]) | 0;
      e = d;
      d = c;
      c = rotl(b, 30);
      b = a;
      a = temp;
    }

    h0 = (h0 + a) | 0;
    h1 = (h1 + b) | 0;
    h2 = (h2 + c) | 0;
    h3 = (h3 + d) | 0;
    h4 = (h4 + e) | 0;
  }

  const out = new Uint8Array(20);
  const odv = new DataView(out.buffer);
  odv.setUint32(0, h0 >>> 0, false);
  odv.setUint32(4, h1 >>> 0, false);
  odv.setUint32(8, h2 >>> 0, false);
  odv.setUint32(12, h3 >>> 0, false);
  odv.setUint32(16, h4 >>> 0, false);
  return out;
}

