// HMAC (RFC 2104) built on a pluggable hash function.
// Only pure JavaScript; no built-in crypto modules.

import { sha1 } from './sha1.mjs';

const BLOCK_SIZE = 64; // SHA-1 block size in bytes

// Computes HMAC-SHA1(key, message). Both inputs are Uint8Array.
// Returns a 20-byte Uint8Array.
export function hmacSha1(key, message) {
  let k = key;
  if (k.length > BLOCK_SIZE) {
    k = sha1(k);
  }
  const paddedKey = new Uint8Array(BLOCK_SIZE);
  paddedKey.set(k);

  const inner = new Uint8Array(BLOCK_SIZE);
  const outer = new Uint8Array(BLOCK_SIZE);
  for (let i = 0; i < BLOCK_SIZE; i++) {
    inner[i] = paddedKey[i] ^ 0x36;
    outer[i] = paddedKey[i] ^ 0x5c;
  }

  const innerMsg = new Uint8Array(BLOCK_SIZE + message.length);
  innerMsg.set(inner);
  innerMsg.set(message, BLOCK_SIZE);
  const innerHash = sha1(innerMsg);

  const outerMsg = new Uint8Array(BLOCK_SIZE + innerHash.length);
  outerMsg.set(outer);
  outerMsg.set(innerHash, BLOCK_SIZE);
  return sha1(outerMsg);
}

