// PBKDF2 (RFC 2898 / PKCS #5 v2.0) with HMAC-SHA1 as the PRF,
// matching the behaviour of the Python `pbkdf2` package defaults.
// Pure JavaScript; no built-in crypto modules.

import { hmacSha1 } from './hmac.mjs';

const PRF_OUT_LEN = 20; // HMAC-SHA1 output length in bytes

// F(P, S, c, i): U_1 = PRF(P, S || INT_32_BE(i)); XOR U_1..U_c.
function deriveBlock(password, salt, iterations, blockIndex) {
  const msg = new Uint8Array(salt.length + 4);
  msg.set(salt);
  msg[salt.length] = (blockIndex >>> 24) & 0xff;
  msg[salt.length + 1] = (blockIndex >>> 16) & 0xff;
  msg[salt.length + 2] = (blockIndex >>> 8) & 0xff;
  msg[salt.length + 3] = blockIndex & 0xff;

  let u = hmacSha1(password, msg);
  const result = new Uint8Array(u);
  for (let i = 1; i < iterations; i++) {
    u = hmacSha1(password, u);
    for (let j = 0; j < PRF_OUT_LEN; j++) {
      result[j] ^= u[j];
    }
  }
  return result;
}

// Derives a key of `dkLen` bytes from password/salt (Uint8Array).
export function pbkdf2(password, salt, iterations, dkLen) {
  const blocks = Math.ceil(dkLen / PRF_OUT_LEN);
  const out = new Uint8Array(dkLen);
  for (let i = 1; i <= blocks; i++) {
    const block = deriveBlock(password, salt, iterations, i);
    const offset = (i - 1) * PRF_OUT_LEN;
    out.set(block.subarray(0, Math.min(PRF_OUT_LEN, dkLen - offset)), offset);
  }
  return out;
}

