// Minimal command-line parser mirroring Python argparse behaviour for:
//   --a (str, required), --b (str, required), --c (int, required)

const PROG = 'test2.mjs';
const USAGE = `usage: ${PROG} [-h] --a A --b B --c C`;

function fail(message) {
  console.error(USAGE);
  console.error(`${PROG}: error: ${message}`);
  process.exit(2);
}

// Parses a value like Python's int(str): optional sign, digits only,
// surrounding whitespace allowed.
function parseIntStrict(value) {
  const s = String(value).trim();
  if (!/^[+-]?\d+$/.test(s)) {
    fail(`argument --c: invalid int value: '${value}'`);
  }
  return parseInt(s, 10);
}

export function parseArgs(argv) {
  const values = { a: undefined, b: undefined, c: undefined };

  for (let i = 0; i < argv.length; i++) {
    let name = argv[i];
    let inlineValue = null;
    if (name.startsWith('--') && name.includes('=')) {
      const eq = name.indexOf('=');
      inlineValue = name.slice(eq + 1);
      name = name.slice(0, eq);
    }
    if (name === '--a' || name === '--b' || name === '--c') {
      let value;
      if (inlineValue !== null) {
        value = inlineValue;
      } else if (i + 1 < argv.length) {
        value = argv[++i];
      } else {
        fail(`argument ${name}: expected one argument`);
      }
      if (name === '--a') values.a = value;
      else if (name === '--b') values.b = value;
      else values.c = value;
    } else {
      fail(`unrecognized arguments: ${argv.slice(i).join(' ')}`);
    }
  }

  const missing = [];
  if (values.a === undefined) missing.push('--a');
  if (values.b === undefined) missing.push('--b');
  if (values.c === undefined) missing.push('--c');
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.join(', ')}`);
  }

  return { a: values.a, b: values.b, c: parseIntStrict(values.c) };
}

