#!/usr/bin/env node
// Entry point: PBKDF2-HMAC-SHA1 key derivation CLI.
// Mirrors /workspace/dataset/pbkdf2/test2.py:
//   result = pbkdf2.PBKDF2(args.a, args.b, iterations=args.c).read(20)
//   print(result.hex())

import { parseArgs } from './lib/argparse.mjs';
import { utf8Encode, toHex } from './lib/bytes.mjs';
import { pbkdf2 } from './lib/pbkdf2.mjs';

const args = parseArgs(process.argv.slice(2));

// 使用指定迭代次数的 PBKDF2
const result = pbkdf2(utf8Encode(args.a), utf8Encode(args.b), args.c, 20); // 派生 20 字节密钥
console.log(toHex(result));

